const script = `from rdkit import Chem

def info(smi,label):
    m=Chem.MolFromSmiles(smi)
    for a in m.GetAtoms(): a.SetAtomMapNum(0)
    Chem.AssignStereochemistry(m, cleanIt=True, force=True)
    Chem.SetBondStereoFromDirections(m)
    centers=Chem.FindMolChiralCenters(m, includeUnassigned=True, useLegacyImplementation=False)
    c=Chem.MolToSmiles(m,isomericSmiles=True)
    # meso test
    mi=Chem.MolFromSmiles(c)
    Chem.AssignStereochemistry(mi,cleanIt=True,force=True)
    for a in mi.GetAtoms():
        if a.GetChiralTag()==Chem.ChiralType.CHI_TETRAHEDRAL_CW: a.SetChiralTag(Chem.ChiralType.CHI_TETRAHEDRAL_CCW)
        elif a.GetChiralTag()==Chem.ChiralType.CHI_TETRAHEDRAL_CCW: a.SetChiralTag(Chem.ChiralType.CHI_TETRAHEDRAL_CW)
    cm=Chem.MolToSmiles(mi,isomericSmiles=True)
    print(f"{label:12s} canon={c:28s} centers(atom,CIP)={centers} meso={c==cm}")

info("[CH3:1][C@H:2]1[CH:3]=[CH:4][CH:5]=[CH:6][C@@H:7]1[CH3:8]","declared")
