from rdkit import Chem
def analyze(path):
    m=Chem.MolFromMolFile(path,removeHs=False); c=m.GetConformer()
    xyz={i:np.array(list(c.GetAtomPosition(i))) for i in range(m.GetNumAtoms())}
    ri=m.GetRingInfo(); ar=[set(r) for r in ri.AtomRings()]
    allr=set().union(*ar)
    nbr=lambda i:[n.GetIdx() for n in m.GetAtomWithIdx(i).GetNeighbors()]
    isC=lambda i:m.GetAtomWithIdx(i).GetAtomicNum()==6
    Cs=[i for i in allr if isC(i)]
    bh=[i for i in Cs if len([n for n in nbr(i) if n in allr])==3]
    oneC=[i for i in Cs if i not in bh and set(n for n in nbr(i) if n in allr)==set(bh)][0]
    # substituent = non-ring C=O/O or C#N carbon attached to ring
    ringC=[i for i in Cs if i not in bh and i!=oneC]  # bridge carbons
    # 6-ring plane = bh + other2carbonbridge + alkene? use all ring atoms of the 6-membered ring
    sixring=[r for r in ar if len(r)==6][0]
    P=np.array([xyz[i] for i in sixring]); cc=P.mean(0); n=np.linalg.svd(P-cc)[2][2]
    sd=lambda i: float(np.dot(xyz[i]-cc,n))
    # substituent atom: non-ring heavy atom attached to a bridge carbon (not in sixring? it is)
    sub=[n for i in Cs for n in nbr(i) if n not in allr]
    v="?"
    if sub:
        # use the carbon of the substituent closest
        sc=sub[0]
        v = "ENDO(subst anti methano)" if np.sign(sd(sc))!=np.sign(sd(oneC)) else "EXO(subst syn methano)"
    return "%s  oneC=%+0.3f subst=%+0.3f -> %s"%(path.split("/")[-1], sd(oneC), sd(sub[0]) if sub else 9, v)
for f in ["2723766","6541030","12268635","721733","12268642"]:
    p=glob.glob("hard_replacements_20261001/HDA_CN/verification/*%s*.sdf"%f)
    if p: print(analyze(p[0]))
